-- Additive language storage: canonical Vietnamese pack IDs remain commerce identities.
create table public.content_pack_translations (
 pack_id text not null references public.content_packs(id),
 locale text not null check (locale = 'en'),
 source_revision text not null,
 metadata jsonb not null,
 question_set jsonb not null,
 published boolean not null default false,
 revision text not null,
 updated_at timestamptz not null default now(),
 primary key(pack_id,locale)
);
create table public.content_pack_translation_versions (
 pack_id text not null references public.content_packs(id),
 locale text not null check (locale = 'en'),
 version text not null,
 question_set jsonb not null,
 primary key(pack_id,locale,version)
);
alter table public.content_pack_translations enable row level security;
alter table public.content_pack_translation_versions enable row level security;
revoke all on public.content_pack_translations, public.content_pack_translation_versions from public, anon, authenticated;
grant all on public.content_pack_translations, public.content_pack_translation_versions to service_role;

create function public.save_content_translation(p_metadata jsonb, p_questions jsonb, p_expected text, p_source_revision text)
returns jsonb language plpgsql security invoker set search_path = public as $$
declare source content_packs; previous content_pack_translations;
 pid text := p_metadata->>'id'; lang text := p_questions->>'locale'; rev text := p_metadata->>'contentVersion';
 merged jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended(pid,0));
 select * into source from content_packs where id=pid for update;
 if source.id is null or source.revision is distinct from p_source_revision then
   return jsonb_build_object('error','source_conflict');
 end if;
 if lang <> 'en' or lang is null or p_metadata->>'locale' is distinct from lang or p_questions->>'packId' is distinct from pid or p_questions->>'contentVersion' is distinct from rev then
   return jsonb_build_object('error','invalid_locale');
 end if;
 -- Same question identities preserve saved progress and trial entitlement across languages.
 if (select jsonb_agg(jsonb_build_array(q->>'id',q->>'type') order by q->>'id') from jsonb_array_elements(p_questions->'questions') q)
    is distinct from (select jsonb_agg(jsonb_build_array(q->>'id',q->>'type') order by q->>'id') from jsonb_array_elements(source.question_set->'questions') q)
    or p_questions->'trialQuestionIds' is distinct from source.question_set->'trialQuestionIds' then
   return jsonb_build_object('error','question_identity_mismatch');
 end if;
 select * into previous from content_pack_translations where pack_id=pid and locale=lang for update;
 if (previous.pack_id is null and p_expected is not null) or
    (previous.pack_id is not null and previous.revision is distinct from p_expected) then
   return jsonb_build_object('error','conflict');
 end if;
 -- Translation editors can only change copy and publication, never pricing or product identity.
 merged := source.metadata || jsonb_build_object('locale',lang,'title',p_metadata->'title','description',p_metadata->'description',
   'contentVersion',rev,'questionFile',p_metadata->'questionFile','published',p_metadata->'published');
 insert into content_pack_translations(pack_id,locale,source_revision,metadata,question_set,published,revision)
 values(pid,lang,source.revision,merged,p_questions,(p_metadata->>'published')::boolean,rev)
 on conflict(pack_id,locale) do update set source_revision=excluded.source_revision, metadata=excluded.metadata,
 question_set=excluded.question_set,published=excluded.published,revision=excluded.revision,updated_at=now();
 if (p_metadata->>'published')::boolean then
   insert into content_pack_translation_versions values(pid,lang,rev,p_questions);
 end if;
 return jsonb_build_object('ok',true,'metadata',merged);
end $$;
revoke all on function public.save_content_translation(jsonb,jsonb,text,text) from public,anon,authenticated;
grant execute on function public.save_content_translation(jsonb,jsonb,text,text) to service_role;

