  and question_set->'questions'='[{"id":"t01","type":"truth","text":"Bạn từng thích thầm ai lâu nhất trong bao lâu?"},{"id":"t02","type":"truth","text":"Điều gì ở một người khiến bạn dễ rung động nhất?"},{"id":"t03","type":"truth","text":"Bạn đã từng giả vờ không thích một người dù thật ra rất thích chưa?"},{"id":"t04","type":"truth","text":"Kỷ niệm tình cảm nào khiến bạn nhớ lâu nhất?"},{"id":"t05","type":"truth","text":"Bạn thích được tỏ tình trực tiếp hay qua tin nhắn hơn?"},{"id":"t06","type":"truth","text":"Nếu được hẹn hò với một người nổi tiếng, bạn sẽ chọn ai?"},{"id":"t07","type":"truth","text":"Bạn từng ghen nhưng cố tỏ ra không quan tâm chưa?"},{"id":"t08","type":"truth","text":"Điều ngọt ngào nhất ai đó từng làm cho bạn là gì?"},{"id":"t09","type":"truth","text":"Bạn có tin tình bạn lâu năm có thể biến thành tình yêu không?"},{"id":"t10","type":"truth","text":"Kiểu tin nhắn nào có thể khiến bạn mỉm cười cả ngày?"},{"id":"t11","type":"truth","text":"Bạn từng chủ động nhắn tin cho crush rồi giả vờ gửi nhầm chưa?"},{"id":"t12","type":"truth","text":"Nếu crush đang ở đây, điều gì bạn muốn nói nhưng có thể không dám nói?"},{"id":"t13","type":"truth","text":"Bạn thích một buổi hẹn lãng mạn hay một buổi hẹn vui nhộn hơn?"},{"id":"t14","type":"truth","text":"Bạn từng đọc lại đoạn chat cũ với người mình thích chưa?"},{"id":"t15","type":"truth","text":"Theo bạn, điểm hấp dẫn nhất của chính mình là gì?"},{"id":"t16","type":"truth","text":"Bạn từng làm điều ngốc nghếch nào để gây chú ý với người mình thích?"},{"id":"t17","type":"truth","text":"Bạn thích người chủ động hay thích tự mình chủ động hơn?"},{"id":"t18","type":"truth","text":"Có lời khen nào bạn từng nhận mà đến giờ vẫn còn nhớ không?"},{"id":"t19","type":"truth","text":"Bạn từng tưởng tượng chuyện yêu đương với một người bạn chưa?"},{"id":"t20","type":"truth","text":"Nếu phải chọn một bài hát mô tả chuyện tình cảm của mình, bạn chọn bài nào?"},{"id":"t21","type":"truth","text":"Bạn dễ bị thu hút bởi ngoại